    fn fill(seed: u32, out: &mut [u8]) {
        for (i, b) in out.iter_mut().enumerate() {
            *b = (i as u32 ^ seed).wrapping_mul(0x9e37_79b9).rotate_left(13) as u8;
        }
    }

    const MODES: [&str; 3] = ["fast", "slow", "nonzero"];

    /// Puts the processor in mode `m` of `MODES`, but for the sleep `fast`
    /// needs; false where it has no AVX2 to do so.
    fn set(m: usize) -> bool {
        if m == 0 {
            vzeroupper();
            return true;
        }
        if !std::is_x86_feature_detected!("avx2") {
            return false;
        }
        // SAFETY: AVX2 is available.
        unsafe {
            if m == 1 {
                asm!("vpcmpeqd ymm0, ymm0, ymm0", "vzeroupper",
                    out("xmm0") _, out("xmm1") _, out("xmm2") _, out("xmm3") _,
                    out("xmm4") _, out("xmm5") _, out("xmm6") _, out("xmm7") _,
                    options(nostack, nomem));
            } else {
                asm!("vpcmpeqd ymm0, ymm0, ymm0", "vpcmpeqd ymm1, ymm1, ymm1",
                    "vpcmpeqd ymm2, ymm2, ymm2", "vpcmpeqd ymm3, ymm3, ymm3",
                    "vpcmpeqd ymm4, ymm4, ymm4", "vpcmpeqd ymm5, ymm5, ymm5",
                    "vpcmpeqd ymm6, ymm6, ymm6", "vpcmpeqd ymm7, ymm7, ymm7",
                    out("xmm0") _, out("xmm1") _, out("xmm2") _, out("xmm3") _,
                    out("xmm4") _, out("xmm5") _, out("xmm6") _, out("xmm7") _,
                    options(nostack, nomem));
            }
        }
        true
    }

    /// The fastest and the median of 41 timings of `f` in mode `m`, set again
    /// before each, in nanoseconds, with XGETBV(1) before and after; `None`
    /// where the mode cannot be set.
    fn time(m: usize, mut f: impl FnMut()) -> Option<(u32, u32, u32, u32)> {
        if !set(m) {
            return None;
        }
        if m == 0 {
            std::thread::sleep(Duration::from_millis(3));
        }
        f();
        let before = xinuse();
        let mut t = [0u32; 41];
        for t in &mut t {
            if m != 0 {
                set(m);
            }
            let start = Instant::now();
            f();
            *t = start.elapsed().as_nanos() as u32;
        }
        let after = xinuse();
        t.sort_unstable();
        Some((before, after, t[0], t[20]))
    }

    pub fn candidates(round: u32) {
        if !std::is_x86_feature_detected!("aes") {
            eprintln!("xsiv {round} skip: the processor has no AES-NI");
            return;
        }
        let mut schedule = [0u8; 240];
        fill(7, &mut schedule);
        let mut block = [0u8; 16];
        fill(11, &mut block);
        block[..4].fill(0);
        // Every candidate leaves what the loop as it is leaves, at lengths
        // that end in a group, in single blocks, and in bytes left alone.
        let run = |f: Cand, bytes: usize| {
            let mut b = Buf([0; BYTES]);
            fill(3, &mut b.0);
            // SAFETY: the schedule's 240 bytes, the block's 16 and `bytes`
            // bytes of data are valid; the functions follow cdecl; the
            // processor has AES-NI.
            unsafe { f(schedule.as_ptr(), 10, block.as_ptr(), 0xffff_fff0, b.0.as_mut_ptr(), bytes as u32) };
            b
        };
        let line = |mode: &str, name: &str, bytes: usize, calls: u32, (before, after, min, med): (u32, u32, u32, u32)| {
            eprintln!(
                "xsiv {round} {mode:<7} {name:<12} {bytes:>5} xinuse {before:#x}->{after:#x} min {:>8.1} median {:>8.1} ns, {:>6} ps/block",
                f64::from(min) / f64::from(calls),
                f64::from(med) / f64::from(calls),
                u64::from(med) * 1000 / (u64::from(calls) * (bytes as u64 / 16))
            );
        };
        for (m, mode) in MODES.iter().enumerate() {
            for (name, f) in CANDS {
                if [BYTES, 16, 95, 96, 100, 1000, 0].iter().any(|&n| run(f, n).0 != run(CANDS[0].1, n).0) {
                    eprintln!("xsiv {round} {mode} {name} WRONG: not what the loop as it is leaves");
                    continue;
                }
                let mut b = Buf([0; BYTES]);
                let p = b.0.as_mut_ptr();
                // SAFETY: as above.
                let t = time(m, || unsafe {
                    f(black_box(schedule.as_ptr()), 10, block.as_ptr(), 1, black_box(p), BYTES as u32)
                });
                if let Some(t) = t {
                    line(mode, name, BYTES, 1, t);
                }
            }
            // The library: AES-128-CTR (the six-block loop, with the key
            // schedule), and AES-128-GCM-SIV's seal at 16 KiB and 1 KiB.
            let key = [0x42u8; 16];
            let mut b = Buf([0; BYTES]);
            if let Some(t) = time(m, || {
                AesCtr::new(black_box(&key), &[0x3c; 16]).unwrap().apply_keystream_final(black_box(&mut b.0));
            }) {
                line(mode, "lib-ctr", BYTES, 1, t);
            }
            for (bytes, calls) in [(BYTES, 1u32), (1024, 16)] {
                let t = time(m, || {
                    for _ in 0..calls {
                        black_box(
                            AesGcmSiv::new(black_box(&key))
                                .unwrap()
                                .encrypt_in_place(&[0x24; 12], &[0x5a; 16], black_box(&mut b.0[..bytes]))
                                .unwrap(),
                        );
                    }
                });
                if let Some(t) = t {
                    line(mode, "lib-siv-seal", bytes, calls, t);
                }
            }
        }
        vzeroupper();
    }
